import{_ as s,o as e,c as n,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"55. Makefiles and Build Automation","description":"The Little Book of C — 55. Makefiles and Build Automation","frontmatter":{"title":"55. Makefiles and Build Automation","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Compilation and Build"],"description":"The Little Book of C — 55. Makefiles and Build Automation","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":55,"sidebarWeight":55,"lang":"en-US","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/055-Makefiles and Build Automation","alternateZh":"/posts/c教程/zh-CN/06-编译与构建/055-Makefiles and Build Automation"},"headers":[],"relativePath":"posts/c教程/en-US/06-Compilation and Build/055-Makefiles and Build Automation.md","filePath":"posts/c教程/en-US/06-Compilation and Build/055-Makefiles and Build Automation.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/06-Compilation and Build/055-Makefiles and Build Automation.md"};function t(l,a,o,c,d,h){return e(),n("div",null,[...a[0]||(a[0]=[p(`<p>[中文版本](/posts/c教程/zh-CN/06-编译与构建/055-Makefiles and Build Automation)</p><p>Compiling one or two C files by hand is fine, but real projects quickly grow to dozens or hundreds of files. Typing long<code>gcc</code> commands every time becomes tedious, error-prone, and inconsistent across environments.</p><p>That’s where Makefiles come in. They automate the build process, track dependencies, and rebuild only what changed.</p><p>Let’s build a complete understanding of how to use<code>make</code> and write simple but powerful Makefiles.</p><h4 id="step-1-what-is-make" tabindex="-1">Step 1. What Is make? <a class="header-anchor" href="#step-1-what-is-make" aria-label="Permalink to &quot;Step 1. What Is make?&quot;">​</a></h4><p><code>make</code> is a tool that reads a file called Makefile and executes the build rules it defines.</p><p>Each rule describes:</p><ol><li>A target (the thing you want to build)</li><li>Its dependencies (what it needs)</li><li>The commands to build it</li></ol><p>Basic syntax:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>target: dependencies</span></span>
<span class="line"><span>&lt;TAB&gt;command</span></span></code></pre></div><p>Yes, the indentation must be a real tab, not spaces.</p><h4 id="step-2-the-simplest-makefile" tabindex="-1">Step 2. The Simplest Makefile <a class="header-anchor" href="#step-2-the-simplest-makefile" aria-label="Permalink to &quot;Step 2. The Simplest Makefile&quot;">​</a></h4><p>Suppose your project has:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main.c</span></span>
<span class="line"><span>math.c</span></span>
<span class="line"><span>math.h</span></span></code></pre></div><p>Makefile:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app: main.c math.c</span></span>
<span class="line"><span>    gcc main.c math.c -o app</span></span></code></pre></div><p>Build:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c math.c -o app</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./app</span></span></code></pre></div><p>Now if you run<code>make</code> again, nothing happens, because<code>make</code> sees that the output (<code>app</code>) is newer than the sources. That’s the magic of dependency tracking.</p><h4 id="step-3-split-into-compilation-steps" tabindex="-1">Step 3. Split into Compilation Steps <a class="header-anchor" href="#step-3-split-into-compilation-steps" aria-label="Permalink to &quot;Step 3. Split into Compilation Steps&quot;">​</a></h4><p>A better version builds<code>.o</code> files separately:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app: main.o math.o</span></span>
<span class="line"><span>    gcc main.o math.o -o app</span></span>
<span class="line"><span>main.o: main.c math.h</span></span>
<span class="line"><span>    gcc -c main.c</span></span>
<span class="line"><span>math.o: math.c math.h</span></span>
<span class="line"><span>    gcc -c math.c</span></span></code></pre></div><p>Now when you change only<code>math.c</code>, only<code>math.o</code> recompiles.</p><h4 id="tiny-code-minimal-project" tabindex="-1">Tiny Code: Minimal Project <a class="header-anchor" href="#tiny-code-minimal-project" aria-label="Permalink to &quot;Tiny Code: Minimal Project&quot;">​</a></h4><p>main.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;math.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;2 + 3 = %d\\n&quot;, add(2, 3));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>math.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b) { return a + b; }</span></span></code></pre></div><p>math.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b);</span></span></code></pre></div><p>Makefile</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app: main.o math.o</span></span>
<span class="line"><span>    gcc main.o math.o -o app</span></span>
<span class="line"><span>main.o: main.c math.h</span></span>
<span class="line"><span>    gcc -c main.c</span></span>
<span class="line"><span>math.o: math.c math.h</span></span>
<span class="line"><span>    gcc -c math.c</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f *.o app</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>./app</span></span>
<span class="line"><span>make clean</span></span></code></pre></div><h4 id="step-4-use-variables" tabindex="-1">Step 4. Use Variables <a class="header-anchor" href="#step-4-use-variables" aria-label="Permalink to &quot;Step 4. Use Variables&quot;">​</a></h4><p>Makefiles support variables to avoid repetition:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -Wextra -std=c99</span></span>
<span class="line"><span>OBJ = main.o math.o</span></span>
<span class="line"><span>app: $(OBJ)</span></span>
<span class="line"><span>    $(CC) $(OBJ) -o app</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) app</span></span></code></pre></div><p>Here:</p><ul><li><code>$&lt;</code>= first dependency</li><li><code>$@</code>= target name</li><li><code>%.o: %.c</code>= pattern rule (applies to all matching files)</li></ul><h4 id="step-5-add-debug-and-release-modes" tabindex="-1">Step 5. Add Debug and Release Modes <a class="header-anchor" href="#step-5-add-debug-and-release-modes" aria-label="Permalink to &quot;Step 5. Add Debug and Release Modes&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -std=c99</span></span>
<span class="line"><span>DEBUG_FLAGS = -g -O0</span></span>
<span class="line"><span>RELEASE_FLAGS = -O2</span></span>
<span class="line"><span>OBJ = main.o math.o</span></span>
<span class="line"><span>TARGET = app</span></span>
<span class="line"><span>all: release</span></span>
<span class="line"><span>debug: CFLAGS += $(DEBUG_FLAGS)</span></span>
<span class="line"><span>debug: $(TARGET)</span></span>
<span class="line"><span>release: CFLAGS += $(RELEASE_FLAGS)</span></span>
<span class="line"><span>release: $(TARGET)</span></span>
<span class="line"><span>$(TARGET): $(OBJ)</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) $(OBJ) -o $(TARGET)</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) $(TARGET)</span></span></code></pre></div><p>Build in debug mode:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make debug</span></span></code></pre></div><p>Build optimized release:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make release</span></span></code></pre></div><h4 id="step-6-automatic-dependencies" tabindex="-1">Step 6. Automatic Dependencies <a class="header-anchor" href="#step-6-automatic-dependencies" aria-label="Permalink to &quot;Step 6. Automatic Dependencies&quot;">​</a></h4><p>You can have<code>gcc</code> generate dependency files automatically:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -MMD -c main.c</span></span></code></pre></div><p>This creates<code>main.d</code> which tracks included headers. You can include these files in your Makefile for automatic rebuilds:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-include $(OBJ:.o=.d)</span></span></code></pre></div><p>That’s how professional build systems keep dependencies accurate.</p><h4 id="step-7-phony-targets" tabindex="-1">Step 7. Phony Targets <a class="header-anchor" href="#step-7-phony-targets" aria-label="Permalink to &quot;Step 7. Phony Targets&quot;">​</a></h4><p>Targets that don’t produce actual files should be marked phony:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.PHONY: clean all debug release</span></span></code></pre></div><p>This prevents file name collisions (e.g., if a file named<code>clean</code> exists).</p><h4 id="step-8-organize-larger-projects" tabindex="-1">Step 8. Organize Larger Projects <a class="header-anchor" href="#step-8-organize-larger-projects" aria-label="Permalink to &quot;Step 8. Organize Larger Projects&quot;">​</a></h4><p>For multi-directory projects:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span> ├── main.c</span></span>
<span class="line"><span> ├── util.c</span></span>
<span class="line"><span>include/</span></span>
<span class="line"><span> ├── util.h</span></span></code></pre></div><p>You can structure your Makefile like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SRC = src/main.c src/util.c</span></span>
<span class="line"><span>OBJ = $(SRC:.c=.o)</span></span>
<span class="line"><span>CFLAGS = -Iinclude -Wall</span></span>
<span class="line"><span>TARGET = app</span></span>
<span class="line"><span>$(TARGET): $(OBJ)</span></span>
<span class="line"><span>    $(CC) $(OBJ) -o $@</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) $(TARGET)</span></span></code></pre></div><p><code>-Iinclude</code> tells the compiler where to find header files.</p><h4 id="step-9-use-built-in-rules" tabindex="-1">Step 9. Use Built-in Rules <a class="header-anchor" href="#step-9-use-built-in-rules" aria-label="Permalink to &quot;Step 9. Use Built-in Rules&quot;">​</a></h4><p><code>make</code> already knows how to build<code>.o</code> from<code>.c</code>. A minimalist Makefile can be:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app: main.o math.o</span></span>
<span class="line"><span>    gcc $^ -o $@</span></span></code></pre></div><p>Where<code>$^</code> expands to all dependencies (<code>main.o math.o</code>).</p><h4 id="step-10-tiny-code-library-build-example" tabindex="-1">Step 10. Tiny Code: Library Build Example <a class="header-anchor" href="#step-10-tiny-code-library-build-example" aria-label="Permalink to &quot;Step 10. Tiny Code: Library Build Example&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -std=c99</span></span>
<span class="line"><span>OBJ = util.o io.o</span></span>
<span class="line"><span>LIB = libtools.a</span></span>
<span class="line"><span>$(LIB): $(OBJ)</span></span>
<span class="line"><span>    ar rcs $(LIB) $(OBJ)</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) $(LIB)</span></span></code></pre></div><p>Build your static library:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span></code></pre></div><p>Now link it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -L. -ltools -o app</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Makefiles give you:</p><ul><li>Reproducible builds, same commands every time</li><li>Incremental recompilation, only changed files rebuild</li><li>Multiple configurations, debug, release, test</li><li>Extensibility, can run scripts, code generation, packaging, etc.</li></ul><p>Every serious C project, from the Linux kernel to tiny embedded tools, relies on<code>make</code> or its descendants (like CMake, Ninja, Meson).</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Create a project with 3<code>.c</code> files and 2<code>.h</code> files.</li><li>Write a Makefile that supports<code>make debug</code>,<code>make release</code>, and<code>make clean</code>.</li><li>Add a<code>make install</code> target that copies the binary to<code>/usr/local/bin</code>.</li><li>Use variables like<code>CC</code>,<code>CFLAGS</code>, and pattern rules to simplify your file list.</li><li>Run<code>make -n</code> to preview commands without executing them.</li></ol><p>In the next section, you’ll learn how to link multiple files and libraries, understanding object files, symbols, and how your code connects together during the build process.</p>`,82)])])}const m=s(i,[["render",t]]);export{u as __pageData,m as default};
